// Everything Thunai says comes from this reviewed script. Nothing spoken on an emergency
// line is generated by a model. Tags such as <pauses> and <slow> are Timbre v3.0 audio tags.
import type { Locality } from "./gazetteer.ts";
import { LEVEL_RANK, type Hazard, type WaterLevel } from "./extract.ts";

export type L = "ta" | "en" | "hi" | "te";

export function langFromCode(code: string | null | undefined): L {
  if (!code) return "ta";
  if (code.startsWith("en")) return "en";
  if (code.startsWith("hi")) return "hi";
  if (code.startsWith("te")) return "te";
  return "ta";
}
export const TTS_LANG: Record<L, string> = { ta: "ta-IN", en: "en-IN", hi: "hi-IN", te: "te-IN" };

interface Lines {
  greeting: string;
  askLocality: string;
  askLocalityAgain: string;
  readBack: (place: string, landmark?: string) => string;
  askWater: string;
  askPeople: string;
  askNeeds: string;
  repeat: string;
  dispatch: Record<1 | 2 | 3, string>;
  close: (ticket: string, p: 1 | 2 | 3, dispatch: string, safety: string) => string;
  safety: { base: string; waterHigh: string; liveWire: string; medical: string; end: string };
  update: (ticket: string, status: string) => string;
  status: Record<"dispatched" | "resolved" | "open", string>;
  priorityWord: Record<1 | 2 | 3, string>;
}

