export function lines(l: L): Lines {
  return S[l];
}

export function placeName(loc: Locality, l: L): string {
  return l === "ta" ? loc.ta : loc.en;
}

export function safetyScript(l: L, water: WaterLevel | undefined, hazards: Hazard[]): string {
  const s = S[l].safety;
  const parts = [s.base];
  if (water && LEVEL_RANK[water] >= LEVEL_RANK.knee) parts.push(s.waterHigh);
  if (hazards.includes("liveWire")) parts.push(s.liveWire);
  if (hazards.includes("medical")) parts.push(s.medical);
  parts.push(s.end);
  return parts.join(" ");
}

/** Text for the screen: audio tags removed. */
export function display(text: string): string {
  return text.replace(/<[a-z ]+>/g, "").replace(/\s+/g, " ").trim();
}
